A reviewer asks what `days_past_due` and `loss_severity_band` mean, how they are populated, and which is safe to use as a model feature. Answer from the dictionary.

GROUNDING PACK (the only facts you may use):
{
  "data_dictionary_entries": [
    {
      "field": "days_past_due",
      "dtype": "float",
      "description": "Days past due at month end. 9999 and -1 appear as sentinel values.",
      "allowed_values": ">=0 expected",
      "source_system": "core_servicing"
    },
    {
      "field": "modification_flag",
      "dtype": "int",
      "description": "1 once a loss-mitigation modification has been applied.",
      "allowed_values": "0|1",
      "source_system": "core_servicing"
    },
    {
      "field": "loss_severity_band",
      "dtype": "category",
      "description": "Realised loss severity band, populated only on default.",
      "allowed_values": "0-10|10-25|25-40|40-60|60+",
      "source_system": "investor_feed"
    },
    {
      "field": "next_12m_default_flag",
      "dtype": "float",
      "description": "1 if the loan reaches 90+ days past due, or a realised credit event, in months t+1..t+12. NaN when right-censored. NOTE: this is a 90+ DPD PROXY, not a realised-default rate - realised credit events occur on ~0.1% of loans.",
      "allowed_values": "0|1|NaN",
      "source_system": "target"
    }
  ],
  "provenance": {
    "source": "data/raw/data_dictionary.csv",
    "llm_role": "retrieval and phrasing only"
  }
}

